                this.error = error;
            });
    }
}

import { wire } from 'lwc';
import getContacts from '@salesforce/apex/ContactController.getContacts';

export default class Good extends LightningElement {
    @wire(getContacts)
    wiredContacts({ data, error }) {
        if (data) {
            this.contacts = data;
        } else if (error) {
            this.error = error;
        }
    }
}

export default class Greeting extends LightningElement {
    renderedCallback() {
        this.template.querySelector('div').textContent = this.name;
    }
}

import { wire } from 'lwc';
import getAccount from '@salesforce/apex/AccountController.getAccount';

export default class AccountName extends LightningElement {
    @wire(getAccount)
    wiredAccount({ data, error }) {
        this.name = data.records[0].Name;
    }
}

export default class OrderRouter extends LightningElement {
    route(order) {
        if (order.type === 'A') {
            if (order.region === 'north') {
                if (order.priority > 5) { return 'A-north-high'; }
                else { return 'A-north-low'; }
            } else if (order.region === 'south') {
                if (order.amount > 1000) { return 'A-south-big'; }
                return 'A-south';
            }
        } else if (order.type === 'B') {
            if (order.region === 'north') { return 'B-north'; }
            else if (order.region === 'south') { return 'B-south'; }
        }
        return 'unknown';
    }
}

